    [{ ...valid, units: [{ id: "u1", prompt: "x", role: "wizard" }] }, /unknown role 'wizard'/],
    [{ ...valid, units: [{ id: "u1", prompt: "x", requires: { minContexts: 1 } }] }, /unknown unit 'u1' requires key 'minContexts'/],
